// --- Helper Functions ---
// Loads data from a JSON file into a vector of strings.
// Returns true on success, false on failure (e.g., file not found).
bool loadData(const string& filePath) {
  ifstream file(filePath);
  if (!file.is_open()) {
    cerr << "Error opening file: " << filePath << endl; // Print error message to stderr
    return false; // Indicate failure
  }

  string line;
  vector<string> data;
  while (getline(file, line)) { // Read each line from the file
    data.push_back(line);     // Add the line to the vector of strings
  }

  file.close(); // Close the file after reading
  return data; // Return the vector of strings
}

// Cleans and preprocesses the data.
// Removes duplicate lines, handles empty lines, converts to lowercase,
// and removes special characters.
bool cleanDataFrame(vector<string>& df) {
  // Remove duplicate lines
  auto it = unique(df.begin(), df.end());
  df.erase(it, df.end());

  // Handle empty lines (replace with "0" - adjust if needed)
  for (auto& row : df) {
    if (row.empty()) {
      row = "0"; // Replace with a default value if needed
    }
  }

  // Convert to lowercase and remove special characters
  for (auto& row : df) {
    size_t start = 0;
    size_t end = row.find_first_not_of("[a-zA-Z0-9\\s]"); // Find the first non-whitespace character
    if (end == string::npos) { // If no non-whitespace character is found (empty string)
      row = ""; // Handle the case where the string is empty
      continue;
    }
    row = row.substr(start, end - start); // Extract the valid part of the string
    transform(row.begin(), row.end(), row.begin(), ::tolower); // Convert to lowercase
  }
  return true; // Indicate success
}

// Processes a single data file.
// Loads the data, cleans it, and performs a basic aggregation (example: printing first row).
bool processData(const string& filePath) {
  vector<string> data = loadData(filePath); // Load data from the file
  if (data.empty()) {
    cout << "No data to process from: " << filePath << endl; // Handle the case where no data was loaded
    return true;  // Exit gracefully;
  }

  if (!cleanDataFrame(data)) { // Clean the data
    cout << "Data cleaning failed for file: " << filePath << endl;
    return false;
  }

  // Example aggregation: Print the first row of the cleaned data.
  cout << "Processed: " << filePath << " - Example Output (first row): " << data[0] << endl;
  return true; // Indicate success
}

// Main function of the program.
int main() {
  vector<string> files;

  // Use filesystem::directory_iterator to list files in the specified directory
  for (const auto& filename : filesystem::directory_iterator(DATA_DIR)) {
    files.push_back(filename.path().string()); // Add the full path to the file
  }

  // Iterate through the list of files and process each one
  for (const auto& file : files) {
    if (processData(file)) { // Process the file
      cout << "Successfully processed: " << file << endl;
    } else {
      cout << "Failed to process: " << file << endl;
    }
  }

  return 0; // Indicate successful program execution
}
