  // Launches threads to process the data.
  for (int i = 0; i < 5; ++i) {
    threads[i] = std::thread(processData, filePath, std::ref(db));
  }

  // Waits for all threads to complete their execution.
  for (int i = 0; i < 5; ++i) {
    threads[i].join();
  }

  // Prints a message indicating that all files have been processed.
  std::cout << "All files processed." << std::endl;

  return 0;
}
```

